Suppose $\{g_j=I_0g_j^\dag:g_j^\dag \in \mathcal{G},j\in\mathbb{J}\}$ is an $\mathcal{L}^2(P_Z)$--orthonormal basis of $\overline{I_0\mathcal{G}}$. Let $\mathcal{P}_{\overline{I_0\mathcal{G}}}:\mathcal{L}^2(P_Z) \rightarrow \overline{I_0\mathcal{G}}$  denote the projection operator. Then 
$ 
Q_{\mathbb{J}}(h)=\Vert\mathcal{P}_{\overline{I_0\mathcal{G}}} \mathcal{T} I_0(h_0^\dag-h)\Vert_2^2. $\label{prop:sum_squares}

For any constant $c \ne0$, any $h_0^\dag$ such that  $h_0=I_0h_0^\dag$ is a solution of equation~\eqref{eq:int_eq_h}, and any $h\in \mathcal{L}^2(P_{W})$, it holds that:
    \begin{enumerate}
    \item 
    If $\mathcal{G}\subset\mathcal{L}^2(P_Z)$ such that $(2c^2)^{-1}\mathcal{T}(h_0^\dag-h)\in\mathcal{G}$ then $ 
         M_P(h) =\Vert I_0\mathcal{T}(h_0^\dag-h)\Vert_2^2.\label{eq:mph} $ 
    \item 
    Suppose $\mathcal{G}$ is a subspace of $\mathcal{L}^2(P_{Z})$. Let $I_0\mathcal{G}:=\left\{I_0g\::\:g\in\mathcal{G}\right\}$ and let $\overline{I_0\mathcal{G}}$ denote its closure in $\mathcal{L}^2(P_Z)$. Let $\{g_j=I_0g_j^\dag:g_j^\dag \in \mathcal{G},\:j\in\mathbb{J}\}$ denote an $\mathcal{L}^2(P_Z)$--orthonormal basis of $\overline{I_0\mathcal{G}}$ where $\mathbb{J}\subseteq\mathbb{N}$. If  $\mathcal{P}_{\overline{I_0\mathcal{G}}}\circ\mathcal{T}_{P}I_0(h_0^\dag-h)\in\ I_0\:\mathcal{G}$, then $ 
    Q_{\mathbb{J}}(h)=M_P(h)$. 
    \end{enumerate}
    \label{prop:innermax}

Let $\mathcal{G}\subset\mathcal{L}^2(P_{Z})$ and let $c \ne 0$ be a constant. If there exists $h_0^\dag$ such that  $h_0=I_0h_0^\dag$ solves equation~\eqref{eq:int_eq_h}, and for any $h\in \mathcal{H}$ it holds that $(2c^2)^{-1}\mathcal{T}_{P}(h_0^\dag-h)\in\mathcal{G}$, then 
\begin{align*}
     &\arg\min_{h \in \mathcal{H}}\left\{\Vert \rho-\mathcal{T}I_0h\Vert_2^2+\lambda_\mathcal{H}\Vert h\Vert^2\right\}\\
     &=\arg\min_{h \in \mathcal{H}}\big[\max_{g\in \mathcal{G}} \mathbb{E}_P\left\{m(O;g)-I_0(X)r(O)h(W)g(Z)-c^2I_0(X)g(Z)^2\right\}+\lambda_\mathcal{H}\Vert h\Vert^2\big].\nonumber                         
\end{align*}
\label{corollary:closed_arg_max}

There exists $\beta >0$ such that $  h_{0,KRAS}^\dag = (T_{\mathcal{H}}\circ\mathcal{T}^* \circ I_0^{op}\circ  \mathcal{T})^{\beta/2} \: h^{*}$ for some $h^{*} \in \mathcal{H}$. Equivalently, 
    \begin{equation}
    h_{0,KRAS}^\dag = (T_{\mathcal{H}}\circ\mathcal{T}^* \circ I_0^{op}\circ \mathcal{T})^{\beta/2} \: T_\mathcal{H}^{1/2} \: h^{**} \quad \text{for some } \: h^{**} \in \mathcal{L}^2(P_W).
    \label{eq:source-kras-basic}
    \end{equation}
    \label{ass:source-basic}

There exists $\beta>0$ and $h^{**}\in\mathcal{L}^2(P_{W})$ such that 
    \begin{align}
h_{0,KRAS}^\dag =T^{1/2}_{\mathcal{H}}\circ\left(\widetilde{\mathcal{T}}^*\circ\widetilde{\mathcal{T}}\right)^{\beta/2} h^{**}=T^{1/2}_{\mathcal{H}}\circ \left( T_\mathcal{H}^{1/2} \circ \mathcal{T}^*\circ  I_0^{op} \circ  \mathcal{T} \circ  T_\mathcal{H}^{1/2}\right)^{\beta/2} \: h^{**}.
\label{eq:source_kras}
    \end{align}
     \label{ass:source}

Suppose that Assumptions \ref{ass:relizability} and \ref{ass:K_H} hold. If, in addition, Assumption \ref{ass:source-basic} or Assumption \ref{ass:source} hold, then there exist constants $c_1^*$ and $c_2^*$ such that 
    \begin{align*}
        \Vert  h_{\lambda_{\mathcal{H}},KRAS}^\dag - h_{0,KRAS}^\dag \Vert_{\mathcal{H}}^2 \le c_1^* \: \lambda_{\mathcal{H}}^{\min\left\{\beta,2\right\}} \:
        \text{and}\:
        \Vert \mathcal{T}I_0(h_{\lambda_{\mathcal{H}},KRAS}^\dag - h_{0,KRAS}^\dag )\Vert_2^2\le c_2^* \:\lambda_{\mathcal{H}}^{\min\left\{\beta+1,2\right\}}.
    \end{align*}
    \label{theo:biascontrol}

Suppose  $m(o;g) = I_0(x)s(o) g(z)$ for some fixed real-valued function $s$ satisfying $\Vert s \Vert_{\infty} < \infty$. Suppose Assumptions \ref{ass:relizability}, \ref{ass:K_H}, \ref{ass:closeness}, \ref{ass:K_G} hold and either Assumption \ref{ass:source-basic} or \ref{ass:source} hold when $P=P_0$. Suppose that the constant $B$ in Assumption \ref{ass:closeness} is taken large enough so that $\big\Vert h_{0,KRAS}^\dag\big\Vert_{\mathcal{H}}\le B$. Let $B_1=B'/c^2$. Define the function class $ 
I_0\cdot\mathcal{G}_{B_1}:=\{I_0\cdot g\: :\: g\in\mathcal{G}_{B_1}\}$ 
    and let $\delta_n$ be an upper bound on the critical radius of $I_0\cdot\mathcal{G}_{B_1}$. If $\lambda_{\mathcal{H}}\le 1$, and $\lambda_\mathcal{G}\ge157c^2\delta_n^2/B_1^2$, then with probability at least $\kappa(\delta_n) :=1-[36+18\cdot I\{\delta_n < 5b/6 \}\cdot\lfloor\{\log(6/5)\}^{-1}\log(b/\delta_n)\rfloor]\exp(-c_1n\delta_n^2)$ 
    where $c_1=\{8b^2(1+17e)\}^{-1}$ and  $b=k_2B_1$,  
    it holds that $\hat{h}_{KRAS} := I_0\:\tilde{h}_{KRAS}$ and $h_{0,KRAS}:=I_0\:h_{0,KRAS}^\dag$ satisfy
  \begin{equation}
      \left\Vert \hat {h}_{KRAS}-h_{0,KRAS}\right\Vert_2^2\le c_2\left(\frac{\delta_n^2}{\lambda_{\mathcal{H}}}+\frac{\lambda_{\mathcal{G}}}{\lambda_{\mathcal{H}}}+\lambda_{\mathcal{H}}^{\min\left\{\beta,1\right\}}\right),\label{eq:strong_error}
  \end{equation}
    and
    \begin{equation}
         \left\Vert\mathcal{T} \left(\hat {h}_{KRAS}-h_{0,KRAS}\right)\right\Vert_2^2\le c_3\left(\delta_n^2+\lambda_{\mathcal{G}}+\lambda_{\mathcal{H}}^{\min\left\{\beta+1,2\right\}}\right),\label{eq:weak_error}
    \end{equation}
    where $c_2$ and $c_3$ are universal constants that depend neither on $n$ nor on $\delta_n$. \label{theo:conv}

We adapted the proof of Theorem 4 of \cite{bennett2023source} to our estimator. To simplify notation, we omit the subscript $KRAS$ from the functions $h_{0,KRAS}^\dag$, $h_{\lambda_\mathcal{H},KRAS}^\dag$, and $\tilde h_{KRAS}$ defined in~\eqref{def:h_0_dag}, \eqref{argmin_h}, and~\eqref{def:h_tilde}. Define $ L(\tau):=\frac{1}{4c^2}\big\Vert I_0\mathcal{T}\big\{h_{0}^\dag-h_{\lambda_\mathcal{H}}^\dag-\tau\big(\tilde h-h_{\lambda_\mathcal{H}}^\dag\big)\big\}\big\Vert_2^2+\lambda_{\mathcal{H}}\big\Vert  h_{\lambda_\mathcal{H}}^\dag+\tau\big(\tilde h- h_{\lambda_\mathcal{H}}^\dag\big)\big\Vert_{\mathcal{H}}^2$. $L(\tau)$ attains its unique global minimum at $\tau=0$ because $h_{\lambda_\mathcal{H}}^\dag$ is the unique minimizer in $\mathcal{H}$ of the criterion in~\eqref{argmin_h}. Then, $L'(0)=0$ and since $L(\tau)$ is quadratic, a Taylor's expansion yields
        \begin{align*}
            L(1)-L(0)&=L'(0)\cdot 1+\frac{1}{2}L''(0)\cdot 1^2=\frac{1}{2}L''(0)=\frac{1}{4c^2}\big\Vert I_0\mathcal{T}\big(\tilde h-h_{\lambda_\mathcal{H}}^\dag\big)\big\Vert_2^2+\lambda_{\mathcal{H}}\big\Vert \tilde h- h_{\lambda_\mathcal{H}}^\dag\big\Vert_{\mathcal{H}}^2.
        \end{align*}
        On the other hand, $L(0) =\frac{1}{4c^2}\Vert   I_0\mathcal{T}(h_0^\dag-h_{\lambda_\mathcal{H}}^\dag)\Vert_2^2+\lambda_{\mathcal{H}}\Vert h_{\lambda_\mathcal{H}}^\dag\Vert_{\mathcal{H}}^2$ and $ L(1)=\frac{1}{4c^2}\Vert  I_0\mathcal{T}(h_0^\dag-\tilde h)\Vert_2^2+\lambda_{\mathcal{H}}\Vert \tilde h\Vert_{\mathcal{H}}^2$.
         Thus, we arrive at 
         \begin{align}
           \frac{1}{4c^2}\big\Vert I_0\mathcal{T}\big(\tilde h-&h_{\lambda_\mathcal{H}}^\dag\big)\big\Vert_2^2+\lambda_{\mathcal{H}}\big\Vert \tilde h- h_{\lambda_\mathcal{H}}^\dag\big\Vert_{\mathcal{H}}^2\label{eq:taylor_exp_L}\\
           &= \frac{1}{4c^2}\Big\{\big\Vert   I_0\mathcal{T}\big(h_0^\dag-\tilde h\big)\big\Vert_2^2-\big\Vert I_0\mathcal{T}\big(h_0^\dag-h_{\lambda_\mathcal{H}}^\dag\big)\big\Vert_2^2\Big\}\nonumber+\lambda_{\mathcal{H}}\Big(\big\Vert \tilde h\big\Vert_{\mathcal{H}}^2-\big\Vert h_{\lambda_\mathcal{H}}^\dag\big\Vert_{\mathcal{H}}^2\Big).
        \end{align}

        To control the right-hand side of~\eqref{eq:taylor_exp_L}, we invoke Lemma~\ref{lemma:erm} which establishes that with probability at least $\kappa(\delta_n)$ the following event happens
        \begin{align*}
    \frac{1}{4c^2}\Big\{\big\Vert I_0 \mathcal{T} \big(h_0^\dag-&\tilde h\big)\big\Vert^2_2-\big\Vert I_0\mathcal{T} \big(h_0^\dag-h\big)\big\Vert^2_2\Big\}+\lambda_{\mathcal{H}}\Big(\big\Vert \tilde h\big\Vert_{\mathcal{H}}^2-\big\Vert h\big\Vert_{\mathcal{H}}^2\Big)\\
     &\quad\quad\quad\le \frac{1}{2c^2}\big\Vert I_0\mathcal{T} \big(h_0^\dag-h\big)\big\Vert^2_2+c_0\delta_n\big\Vert  I_0\mathcal{T}\big(\tilde h-h\big)\big\Vert_2+\lambda_{\mathcal{G}}B_1^2+c_0'\delta^2_n
\end{align*}
        where $c_0=9\cdot\max\{\Vert s\Vert_\infty,\:\Vert r\Vert_\infty\cdot k_1B,\: 2c^2b\}/(c^2 b)$ and $c'_0=c^2\cdot c_0(2_3c_0+\max\{2,2c_0/9\})$.

        Hence, identity~\eqref{eq:taylor_exp_L} implies that, with probability at least $\kappa(\delta_n)$, the following holds
        \begin{align*}
           \frac{1}{4c^2}\big\Vert I_0\mathcal{T}\big(\tilde h-h_{\lambda_\mathcal{H}}^\dag\big)\big\Vert_2^2&+\lambda_{\mathcal{H}}\big\Vert \tilde h- h_{\lambda_\mathcal{H}}^\dag\big\Vert_{\mathcal{H}}^2\\
           &\le   \frac{1}{2c^2}\big\Vert  I_0\mathcal{T}\big(h_0^\dag-h_{\lambda_\mathcal{H}}^\dag\big)\big\Vert_2^2+c_0\delta_n\big\Vert I_0\mathcal{T}\big(\tilde h-h_{\lambda_\mathcal{H}}^\dag\big)\big\Vert_2+\lambda_{\mathcal{G}}B_1^2+c'_0\delta_n^2.
        \end{align*}

        By the AM-GM inequality, $c_0\delta_n\Vert I_0\mathcal{T}(\tilde h-h_{\lambda_\mathcal{H}}^\dag)\Vert_2 \le 2c^2\cdot c_0^2 \delta_n^2 +\frac{1}{8c^2}\Vert I_0\mathcal{T}(\tilde h-h_{\lambda_\mathcal{H}}^\dag)\Vert_{2}^2$,
       which combined with the right-hand side of the last display yields that
        \begin{align}
             \lambda_{\mathcal{H}}\big\Vert \tilde h-h_{\lambda_\mathcal{H}}^\dag\big\Vert_{\mathcal{H}}^2+\frac{1}{8c^2}\big\Vert I_0\mathcal{T}\big(\tilde h-h_{\lambda_\mathcal{H}}^\dag\big)\big\Vert_2^2&\le  \frac{1}{2c^2}\big\Vert I_0\mathcal{T}\big(h_0^\dag-h_{\lambda_\mathcal{H}}^\dag\big)\big\Vert_2^2+\lambda_{\mathcal{G}}B_1^2+c_0''\delta_n^2,\label{useful_exp}
        \end{align}
        with $c_0''=c'_0+2c^2\cdot c_0^2$, happens with probability at least $\kappa(\delta_n)$, which, in turn, implies that
      $ 
        \lambda_{\mathcal{H}}\Vert \tilde h-h_{\lambda_\mathcal{H}}^\dag\Vert_{\mathcal{H}}^2\le  \frac{1}{2c^2}\Vert I_0\mathcal{T} (h_0^\dag-h_{\lambda_\mathcal{H}}^\dag)\Vert_2^2+\lambda_{\mathcal{G}}B_1^2+c_0''\delta_n^2
       $ also holds with probability at least $\kappa(\delta_n)$.

       Applying the inequality $\Vert h_1+h_2\Vert_{\mathcal{H}}^2\le 2\Vert h_1\Vert_{\mathcal{H}}^2+2\Vert h_2\Vert_{\mathcal{H}}^2$ we then obtain that the event
        \begin{align*}
            \big\Vert \tilde h-h_0^\dag\big\Vert_{\mathcal{H}}^2
            \le& \:2\big\Vert \tilde h-h_{\lambda_\mathcal{H}}^\dag\big\Vert_{\mathcal{H}}^2+2\big\Vert h_{\lambda_\mathcal{H}}^\dag-h_0^\dag\big\Vert_{\mathcal{H}}^2\\
            \le& \frac{1}{c^2\cdot\lambda_{\mathcal{H}}}\big\Vert I_0\mathcal{T}\big(h_0^\dag-h_{\lambda_\mathcal{H}}^\dag\big)\big\Vert_2^2+\frac{2\lambda_{\mathcal{G}}B_1^2}{\lambda_{\mathcal{H}}}+\frac{2c_0''\delta_n^2}{\lambda_{\mathcal{H}}}+2\big\Vert h_{\lambda_\mathcal{H}}^\dag-h_0^\dag\big\Vert_{\mathcal{H}}^2,
        \end{align*}
        happens with probability at least $\kappa(\delta_n)$.
       Because $\tilde h-h_0^\dag\in\mathcal{H}$, it follows that $ \Vert \tilde h-h_0^\dag\Vert_2^2\le k_1^2 \: \Vert \tilde h-h_0^\dag\Vert_{\mathcal{H}}^2$. Hence, invoking Theorem \ref{theo:biascontrol} to bound the terms $\Vert I_0\mathcal{T}(h_0^\dag-h_{\lambda_{\mathcal{H}}}^\dag)\Vert_2^2$ and $\Vert h_{\lambda_{\mathcal{H}}}^\dag-h_0^\dag\Vert_{\mathcal{H}}^2$, we conclude that, with probability at least $\kappa(\delta_n)$,
  $ \Vert \tilde h-h_0^\dag\Vert_2^2\le c_2\big(\frac{\delta_n^2}{\lambda_{\mathcal{H}}}+\frac{\lambda_{\mathcal{G}}}{\lambda_{\mathcal{H}}}+\lambda_{\mathcal{H}}^{\min\left\{\beta,1\right\}}\big),
    $ where $ c_2=k_1^2\cdot\max\{2c_1^*+c_2^*c^{-2}\:,\: 2B_1^2\:,\:2c_0''\}$, and $c_1^*$ and $c_2^*$ are the constants of Theorem~\ref{theo:biascontrol}.

   To derive the bound for $\Vert I_0\mathcal{T}(\tilde h-h_0^\dag)\Vert_2^2$, first note that from inequality~\eqref{useful_exp} we have that the event
\begin{align*}
             \frac{1}{8c^2}\big\Vert I_0\mathcal{T}\big(\tilde h-h_{\lambda_{\mathcal{H}}}^\dag\big)\big\Vert_2^2&\le  \frac{1}{2c^2}\big\Vert I_0\mathcal{T}\big(h_0^\dag-h_{\lambda_{\mathcal{H}}}^\dag\big)\big\Vert_2^2+\lambda_{\mathcal{G}}B_1^2+c_0''\delta_n^2
        \end{align*}
        happens with probability at least $\kappa(\delta_n)$. Combining this inequality with the inequality $ \Vert I_0\mathcal{T}(\tilde h-h_0^\dag)\Vert_2^2\le 2\Vert I_0\mathcal{T}(\tilde h-h_{\lambda_{\mathcal{H}}}^\dag)\Vert_2^2+2\Vert I_0\mathcal{T}(h_{\lambda_{\mathcal{H}}}^\dag-h_0^\dag)\Vert_2^2$  we conclude that
\begin{align*}
            \big\Vert I_0\mathcal{T}\big(\tilde h-h_0^\dag\big)\big\Vert_2^2\le 10\big\Vert I_0\mathcal{T}\big(h_0^\dag-h_{\lambda_{\mathcal{H}}}^\dag\big)\big\Vert_2^2+16c^2B_1^2\lambda_{\mathcal{G}}+16c^2c_0''\delta_n^2
         \end{align*}
         holds with probability at least $\kappa(\delta_n)$. Invoking again Theorem \ref{theo:biascontrol} to bound $\Vert I_0\mathcal{T}(h_0^\dag-h_{\lambda_{\mathcal{H}}}^\dag)\Vert_2^2$, we conclude that the event 
$ \Vert I_0\mathcal{T}(\tilde h-h_0^\dag)\Vert_2^2\le c_3\left(\delta_n^2+\lambda_{\mathcal{G}}+\lambda_{\mathcal{H}}^{\min\left\{\beta+1,2\right\}}\right) $ happens with probability at least $\kappa(\delta_n)$ 
    where $c_3=\max\{10 c_2^*\:,\:16c^2B_1^2\:,\:16c^2c_0''\}$. This completes the proof.

As discussed in Section \ref{sec:conv_analysis}, Assumption \ref{ass:K_H} implies that the integral operator $T_\mathcal{H}:\mathcal{L}^2(P_{0,W})\mapsto\mathcal{L}^2(P_{0,W})$ is compact and positive. Therefore, by the spectral decomposition theorem (see, e.g., Theorem 4.3 of \cite{hohage2002lecture}) there exists eigenfunctions $(\varphi_j)_{j=1}^N$ corresponding to all the non-zero eigenvalues $ (\eta_j)_{j=1}^N$ of $T_{\mathcal{H}}$, where $N\in\mathbb{N}\cup\left\{+\infty\right\}$. Such eigenfunctions are orthonormal in $\mathcal{L}^2(P_{0,W})$ and satisfy that for any $h \in \mathcal{L}^2(P_{0,W})$, it holds that $T_{\mathcal{H}}h=\sum_{j=1}^N\eta_j\langle h,\varphi_j\rangle_2\varphi_j$. Because the integral operator $T_\mathcal{H}$ is positive, its non-zero eigenvalues $ (\eta_j)_{j=1}^N$ are positive. When $N=\infty$, $\eta_j \rightarrow 0$  as $j \rightarrow \infty$ and the sequence $ (\eta_j)_{j=1}^N$ is arranged in decreasing order. The square root of $T_{\mathcal{H}}$, denoted by $T_{\mathcal{H}}^{1/2}$, is defined by $T_{\mathcal{H}}^{1/2}h:=\sum_{j=1}^N \sqrt{\eta_j}\langle h,\varphi_j\rangle_2\varphi_j$.

Assertion (a) follows from the fact that for any $h\in\mathcal{L}^2(P_{0,W})$: $T_{\mathcal{H}}h=\sum_{j=1}^N\eta_j\langle h,\varphi_j\rangle_2\varphi_j=0$ iff $\langle h,\varphi_j\rangle_2=0\:\forall j=1,\dots,N$ iff $T_{\mathcal{H}}^{1/2}h=\sum_{j=1}^N\sqrt{\eta_j}\langle h,\varphi_j\rangle_2\varphi_j=0$.

Another result (see Theorem 11.18 of \cite{paulsen2016introduction}), establishes that under Assumption~\ref{ass:K_H}, the sequence $(\sqrt{\eta_j}\varphi_j)_{j=1}^N$ forms an orthogonal basis of the RKHS $\mathcal{H}$. Furthermore,  $\mathcal{H}$ admits the representation 
\begin{align}
 \mathcal{H}=\left\{h=\sum_{j=1}^N\gamma_j\varphi_j \: : \: \text{ for some } (\gamma_j)_{j=1}^{\infty}\text{ with }\sum_{j=1}^N\frac{\gamma_j^2}{\eta_j}<\infty\right\},\label{H_rep}
\end{align}
where if $N=\infty$, the limit of the finite sums is with respect to the $\mathcal{L}^2(P_{0,W})$-metric. 
Additionally, its inner product decomposes as (see Theorem 11.3 of \cite{paulsen2016introduction}) $\langle h,h'\rangle_{\mathcal{H}}=\sum_{j=1}^N\langle h,\varphi_j\rangle_2\langle h',\varphi_j\rangle_2/\eta_j$.

Assertion (b) follows from the representation of $\mathcal{H}$ in~\eqref{H_rep} and the definition of $T_{\mathcal{H}}^{1/2} h$. Specifically, for any $h \in \mathcal{L}^2(P_{0,W})$, we have $T_{\mathcal{H}}^{1/2}h=\sum_{j=1}^N\sqrt{\eta_j}\langle h,\varphi_j\rangle_2\varphi_j$, so to show that $T_{\mathcal{H}}^{1/2}h$ is in $\mathcal{H}$ we need to show that $\sum_{j=1}^N(\sqrt{\eta_j}\langle h,\varphi_j\rangle_2)^2/\eta_j < \infty$. This holds because
\begin{equation}
\sum_{j=1}^N\frac{\left(\sqrt{\eta_j}\langle h,\varphi_j\rangle_2\right)^2}{\eta_j}=\sum_{j=1}^N\langle h,\varphi_j\rangle_2^2\le \Vert h\Vert_2^2<\infty.\label{eq:th_norm}
\end{equation}
 Assertion (c) follows from~\eqref{eq:th_norm} since $\Vert T^{1/2}_\mathcal{H}h\Vert_\mathcal{H}^2 = \sum_{j=1}^N\left(\sqrt{\eta_j}\langle h,\varphi_j\rangle\right)^2/\eta_j$, thus proving that $T^{1/2}_\mathcal{H}$ is bounded with operator norm at most one. The linearity of $T^{1/2}_\mathcal{H}$ is immediate from the linearity of the inner products \(\langle h, \varphi_j \rangle_2\), completing the proof of (c).

To show Assertions (d) and (e), we use that $\mathcal{N}(T_\mathcal{H})^\perp=\text{span}(\varphi_1,\dots,\varphi_N)$. Assertion (d) follows because, for $h\in\text{span}(\varphi_1,\dots,\varphi_N)$, the first inequality in~\eqref{eq:th_norm} becomes an equality.

To prove Assertion (e), we first show that $T_{\mathcal{H}}^{1/2}:\mathcal{N}(T_\mathcal{H})^\perp \rightarrow \mathcal{H}$ is injective. Let $h_1,h_2\in\mathcal{N}(T_\mathcal{H})^\perp$ be such that $T_\mathcal{H}^{1/2}h_1=T_\mathcal{H}^{1/2}h_2$. Then, $h_1-h_2\in\mathcal{N}(T_\mathcal{H}^{1/2})$. By part (a), $\mathcal{N}(T_\mathcal{H}^{1/2}) = \mathcal{N}(T_\mathcal{H})$. Then, $h_1-h_2\in\mathcal{N}(T_\mathcal{H}) \cap \mathcal{N}(T_\mathcal{H})^\perp =\{0\}$. This shows injectivity. Surjectivity follows from the representation of $\mathcal{H}$ in (\ref{H_rep}). Specifically, any $h\in\mathcal{H}$ can be written as $h=\sum_{j=1}^N\gamma_j\varphi_j$ with $\sum_{j=1}^N\frac{\gamma_j^2}{\eta_j}<\infty$.
Then $T_\mathcal{H}^{1/2}h'=h$ where $h':=\sum_{j=1}^N\gamma_j\varphi_j/\sqrt{\eta_j}\in\mathcal{N}(T_\mathcal{H})^\perp$.

Assertion (f) follows from the definition of $\mathcal{T}_{\mathcal{H}}^{1/2}:\mathcal{L}^2(P_{0,W})\mapsto\mathcal{L}^2(P_{0,W})$, as it is the norm-limit of finite-rank operators (see Proposition 5.6.5 of \cite{conway2012course}).

To prove assertion (g), observe that for any $h'\in\mathcal{L}^2(P_W)$ and $h\in\mathcal{H}$, it holds that $ \langle T_\mathcal{H}h',h\rangle_\mathcal{H}=\sum_{j=1}^N\langle T_\mathcal{H}h',\varphi_j\rangle_2\langle h,\varphi_j\rangle_2/\eta_j=\sum_{j=1}^N\langle h',\varphi_j\rangle_2\langle h,\varphi_j\rangle_2=\langle h',\sum_{j=1}^N\langle h,\varphi_j\rangle_2\varphi_j\rangle_2$.
For every $h\in\mathcal{H}$, $h=\sum_{j=1}^N\langle h,\varphi_j\rangle_2\varphi_j$. Hence, the last expression equals $\langle h',h\rangle_2$.

Suppose that:
\begin{enumerate}
    \item $\mathcal{F}$ is a separable metric space with metric $d$, and let $\mathcal{S}\subset\mathcal{F}$ be a countable dense set,
    \item For each $f\in\mathcal{F}$, $t_f:\mathcal{O}\mapsto\mathbb{R}$ is a measurable function,  where $\mathcal{O}$ is the sample space of a random vector $O$,
    \item For each $o\in\mathcal{O}$, the map $f\mapsto t_f(o)$ is continuous with respect to $d$ at all $f \in \mathcal{F}$.
\end{enumerate}
Then for all $o_1,\dots,o_n\in\mathcal{O}$, $\sup_{f\in\mathcal{F}}\left\{\frac{1}{n}\sum_{i=1}^nt_f(o_i) \right \} = \sup_{f\in\mathcal{S}}\left\{\frac{1}{n}\sum_{i=1}^nt_f(o_i)\right\}$ and, consequently, for $O_1,\cdots,O_n$ i.i.d. copies of $O$, $\sup_{f\in\mathcal{F}}\left\{\frac{1}{n}\sum_{i=1}^nt_f(O_i)\right\}$ is a well-defined random variable.
    \label{lemma:countable}

Let $\mathcal{O}_0\subset\mathcal{O}$ be a measurable set. Suppose that:
\begin{enumerate}
    \item $\mathcal{F}$ is a separable metric space with metric denoted by $d$ such that $\mathcal{F}\subset\mathcal{L}^2(P_O)$, and let $\mathcal{S}$ denote a countable dense subset of it,
    \item For each $f\in\mathcal{L}^2(P_O)$, $t_f:\mathcal{O}\mapsto\mathbb{R}$ is a measurable function,  where $\mathcal{O}$ is the sample space of a random vector $O$,
    \item For each $o\in\mathcal{O}$, the map $f\mapsto t_{I_{\mathcal{O}_0}\cdot f}(o)$ is continuous with respect to $d$ at all $f \in \mathcal{F}$.
    \item The map $f\mapsto t_{I_{\mathcal{O}_0}\cdot f}$ is continuous from $(\mathcal{F},d)$ into $\mathcal{L}^1(P_O)$.
\end{enumerate}
For given fixed $\beta\in\mathbb{R}$ and any $o\in\mathcal{O}$, define the map $f\in\mathcal{F}\mapsto h_f(o):= t_{I_{\mathcal{O}_0}\cdot f}(o)-\beta\cdot\mathbb{E}\{t_{I_{\mathcal{O}_0}\cdot f}(O)\}$. Given $\mathcal{F}'\subset\mathcal{F}$, define $S':=\mathcal{F}'\cap\mathcal{S}$. Then,
\begin{enumerate}
    \item[i)] $\sup_{f\in \mathcal{F}'}\left\vert \frac{1}{n}\sum_{i=1}^nh_f(O_i) \right\vert
= \sup_{f \in \mathcal{S}'}\left\vert \frac{1}{n}\sum_{i=1}^nh_f(O_i) \right\vert$. In particular, the left-hand side is a well-defined random variable.
\item[ii)] When $\beta=0$, the conclusion in i) holds even if assumption 4 fails.
\end{enumerate}
 \label{corollary:countable_Lf}

Fix $o\in\mathcal{O}$. First, we show that the map $f\mapsto h_f(o)$ is continuous with respect to the metric $d$. Take $f_1,f_2\in\mathcal{F}$. By triangle inequality, we have $ \vert h_{f_1}(o)-h_{f_2}(o)\vert\le \vert t_{I_{\mathcal{O}_0}\cdot f_1}(o)-t_{I_{\mathcal{O}_0}\cdot f_2}(o)\vert +|\beta|\cdot\mathbb{E}_P\{\vert  t_{I_{\mathcal{O}_0}\cdot f_1}(O)-t_{I_{\mathcal{O}_0}\cdot f_2}(O)\vert\}$.

Let $\varepsilon>0$. By assumption 3, there exists $\delta>0$ such that if $d(f_1,f_2)<\delta$, then $\left\vert t_{I_{\mathcal{O}_0}\cdot f_1}(o)-t_{I_{\mathcal{O}_0}\cdot f_2}(o)\right\vert <\varepsilon/2$. By assumption 4, there exists $\delta'>0$ such that  if $d(f_1,f_2)<\delta'$, then $|\beta|\cdot\mathbb{E}_P\{\vert  t_{I_{\mathcal{O}_0}\cdot f_1}(O)-t_{I_{\mathcal{O}_0}\cdot f_2}(O)\vert\}<\varepsilon/2$. Then, if $d(f_1,f_2)<\min\{\delta,\delta'\}$, we have $ \vert h_{f_1}(o)-h_{f_2}(o)\vert<\varepsilon$.

By Assumption 1 and definition of $\mathcal{F}'$, 
$\mathcal{F}'$ is separable with respect to $d$ with dense subset $\mathcal{S}'$. Then, it follows from Lemma~\ref{lemma:countable} that 
\[
\sup_{f\in \mathcal{F}'} \Big\{\frac{1}{n}\sum_{i=1}^nh_f(O_i) \Big\}
= \sup_{f \in \mathcal{S}'} \Big\{\frac{1}{n}\sum_{i=1}^nh_f(O_i) \Big\},\: \sup_{f\in \mathcal{F}'} \Big\{-\frac{1}{n}\sum_{i=1}^nh_f(O_i) \Big\}
= \sup_{f \in \mathcal{S}'} \Big\{-\frac{1}{n}\sum_{i=1}^nh_f(O_i) \Big\},
\]
and the left hand sides of both equalities are well-defined random variables. Therefore
\begin{align*}
    \sup_{f\in \mathcal{F}'} \Big\vert\frac{1}{n}\sum_{i=1}^nh_f&(O_i) \Big\vert = \max\Bigg\{\sup_{f\in \mathcal{F}'} \Big[\frac{1}{n}\sum_{i=1}^nh_f(O_i) \Big],\sup_{f\in \mathcal{F}'} \Big[-\frac{1}{n}\sum_{i=1}^nh_f(O_i) \Big]\Bigg\}
    \\
    &=\max\Bigg\{\sup_{f\in \mathcal{S}'} \Big[\frac{1}{n}\sum_{i=1}^nh_f(O_i) \Big],\sup_{f\in \mathcal{S}'} \Big[-\frac{1}{n}\sum_{i=1}^nh_f(O_i) \Big]\Bigg\}=\sup_{f\in \mathcal{S}'} \Big\vert\frac{1}{n}\sum_{i=1}^nh_f(O_i) \Big\vert
\end{align*}
and the leftmost hand side is a well-defined random variable. This concludes the proof.

Suppose the assumptions of Lemma \ref{lemma:lemma11foster} hold. Let $h_f$ and $Z_n(r) $ be defined as in Lemma \ref{lemma:lemma11foster} and let $\delta_n$ be any solution to the inequality $\mathcal{R}_n\left(star\left(I_{\mathcal{O}_0}\cdot\mathcal{F}\right),\delta\right)\le\frac{\delta^2}{b}$. Set $c_1=\left\{8b^2(1+17e)\right\}^{-1}$. Then, 
\begin{equation}
\big\vert\frac{1}{n}
\sum_{i=1}^n h_f(O_i) \big\vert \le 
\frac{6L\delta_n}{b} \left\{ \left\Vert I_{\mathcal{O}_0}\cdot f \right\Vert_2 + \delta_n \right\} \quad \forall f\in\mathcal{F}
\label{emp_process}
\end{equation}
happens with probability at least 
$1-\{4+2I\{\delta_n<5b/6\}\lfloor\{\log(6/5)\}^{-1}\log(b/\delta_n)\rfloor\}\exp(-c_1n\delta_n^2)$.
\label{lemma:lemma14foster}

Under the assumptions of Theorem~\ref{theo:conv} and with the constants defined as in that Theorem, the following event happens for any $h\in \mathcal{H}_{B}$:
\begin{align*}
    \frac{1}{4c^2}\Big\{\big\Vert I_0 \mathcal{T} \big(h_0^\dag-&\tilde h\big)\big\Vert^2_2-\big\Vert I_0\mathcal{T} \big(h_0^\dag-h\big)\big\Vert^2_2\Big\}+\lambda_{\mathcal{H}}\Big(\big\Vert \tilde h\big\Vert_{\mathcal{H}}^2-\big\Vert h\big\Vert_{\mathcal{H}}^2\Big)\\
     &\quad\quad\quad\le \frac{1}{2c^2}\big\Vert I_0\mathcal{T} \big(h_0^\dag-h\big)\big\Vert^2_2+c_0\delta_n\big\Vert  I_0\mathcal{T}\big(\tilde h-h\big)\big\Vert_2+\lambda_{\mathcal{G}}B_1^2+c_0'\delta^2_n.
\end{align*}
\label{lemma:erm}

For any $h\in\mathcal{H}_{B}$, define $g_h:=\frac{1}{2c^2}\mathcal{T}(h_0^\dag-h)$. Since $\Vert h_0^\dag-h\Vert_{\mathcal{H}}\le\Vert h_0^\dag\Vert_{\mathcal{H}}+\Vert h\Vert_{\mathcal{H}}\le 2B$, Assumption~\ref{ass:closeness} of the main text implies that $g_h\in\mathcal{G}_{B_1}$ where $B_1:=B'/c^2$. In addition, for any $h\in\mathcal{H}_{B}$, we have $\sup_{w\in\mathcal{W}}|h(w)|\le k_1 B $, so the function class $\mathcal{H}_B$ is uniformly bounded by $k_1 B$. Similarly, the function class $\mathcal{G}_{B_1}$ is uniformly bounded by $k_2B_1$.

 By part 1 of Proposition~\ref{prop:innermax} and Assumption~\ref{ass:closeness}, we have
 \[
  \frac{1}{4c^2}\big\Vert I_0 \mathcal{T} \big(h_0^\dag-\tilde h\big)\big\Vert^2_2= \mathbb{E}_{P_0}\big\{I_0(X)s(O)g_{\tilde h}(Z)-I_0(X)r(O)\tilde h(W)g_{\tilde h}(Z)-c^2\cdot I_0(X)g_{\tilde h}(Z)^2\big\},
 \]
 where the expectation in the right hand-side is with respect to $O$, and $\tilde h$ is regarded as a fixed, non-random function.

Next, we apply Lemma~\ref{lemma:lemma14foster} to bound the expectation of each of the three terms in the right hand side of the last display. Specifically, with $c_1:=\left\{8b^2(1+17e)\right\}^{-1}$, $c_2:=6L'/b$, $b:=k_2B_1$, $\xi(\delta_n):=\{4+2I\{\delta_n<5b/6\}\lfloor\{\log(6/5)\}^{-1}\log(b/\delta_n)\rfloor\}\:\exp(-c_1n\delta_n^2)$, and
\begin{equation}
    L'=\max\{\Vert s\Vert_\infty,\:\Vert r\Vert_\infty\cdot k_1B,\: 2c^2\cdot b\},\label{def:Lmax}
\end{equation}
applying Lemma~\ref{lemma:lemma14foster}, we can conclude that
\begin{enumerate}
    \item[I.] With probability at least $1-\xi(\delta_n)$, the following event happens
\begin{equation}
    \Big\vert \mathbb{E}_n\big[I_o(X)s(O)g(Z) - \mathbb{E}_{P_0}\left\{I_0(X)s(O)g(Z)\right\} \big]\Big \vert \le c_2\delta_n\left\{\left\Vert I_0g\right\Vert_2+\delta_n\right\} \quad \forall {g \in \mathcal{G}_{B_1}}. \label{eq:term1sup}
\end{equation}
In particular, $\mathbb{E}_{P_0}\{I_0(X)s(O)g_{\tilde h}(Z)\}\le \mathbb{E}_n\{I_0(X)s(O)g_{\tilde h}(Z)\}+ c_2\delta_n\{\Vert I_0g_{\tilde h}\Vert_2+\delta_n\}$ holds with probability at least $1-\xi(\delta_n)$.

\item[II.] With probability at least $1-\xi(\delta_n)$, for all $g \in \mathcal{G}_{B_1}$, the following event happens
\begin{equation}
    \Big\vert \mathbb{E}_n\big[I_0(X)r(O)\tilde h(W)g(Z) - \mathbb{E}_{P_0}\{I_0(X)r(O)\tilde h(W)g(Z)\} \big]\Big \vert \le c_2\delta_n\{\left\Vert I_0g\right\Vert_2+\delta_n\}. \label{eq:term2sup}
\end{equation}
Notably, $-\mathbb{E}_{P_0}\{I_0(X)r(O)\tilde h(W)g_{\tilde h}(Z)\}\le -\mathbb{E}_n\{I_0(X)r(O)\tilde h(W)g_{\tilde h}(Z)\}+ c_2\delta_n\{\Vert I_0g_{\tilde h}\Vert_2+\delta_n\}$ holds with probability at least $1-\xi(\delta_n)$.
\item[III.]  With probability at least $1-\xi(\delta_n)$, the following event happens
\begin{equation}
    \Big\vert \mathbb{E}_n\big[c^2 I_0(X)g(Z)^2 - \mathbb{E}_{P_0}\{c^2 I_0(X)g(Z)^2\} \big]\Big \vert \le c_2\delta_n\{\Vert I_0g\Vert_2+\delta_n\} \quad \forall {g \in \mathcal{G}_{B_1}}. \label{eq:term3sup}
\end{equation}
In particular, $ -\mathbb{E}_{P_0}\{c^2 I_0(X)g_{\tilde h}(Z)^2\}\le -\mathbb{E}_n\{c^2 I_0(X)g_{\tilde h}(Z)^2\}+ c_2\delta_n\{\Vert I_0g_{\tilde h}\Vert_2+\delta_n\}$ holds with probability at least $1-\xi(\delta_n)$.
\end{enumerate}

To apply Lemma~\ref{lemma:lemma14foster} to prove (I), (II), and (III), we define convenient function classes $\mathcal{F}$, maps $f \in \mathcal{L}^2(P_{0,O})\mapsto t_f$, and sets $\mathcal{O}_0$. For these objects, we argue that the following conditions hold:

 \begin{enumerate}
    \item[a.] $\mathcal{F}$ is a separable metric space with metric denoted by $d$ such that $\mathcal{F}\subset\mathcal{L}^2(P_{0,O})$ and: (a.1) $\mathcal{F}$ is uniformly bounded by $b$, (a.2) for each $o\in\mathcal{O}$, the evaluation functional $f\mapsto f(o)$ is continuous relative to the metric $d$, and (a.3) $f=0$ belongs to $\mathcal{F}$.
    \item[b.] For each $f\in\mathcal{L}^2(P_{0,O})$, $t_f:\mathcal{O}\mapsto\mathbb{R}$ is a measurable function.
    \item[c.] For each $o\in\mathcal{O}$, the map $f\mapsto t_{I_{\mathcal{O}_0}\cdot f}(o)$ is continuous with respect to $d$ at all $f \in \mathcal{F}$.
    \item[d.] The map $f\mapsto t_{I_{\mathcal{O}_0}\cdot f}$ is continuous from $(\mathcal{F},d)$ to $\mathcal{L}^1(P_{0,O})$. 
    \item[e.] $t_f$ satisfies $t_f=0$ when $f=0$.
    \item[f.] $\exists L$ such that for any $f_1,f_2\in\mathcal{L}^2(P_{0,O})$, $|t_{f_1}(o)-t_{f_2}(o)|\le L\left\vert f_1(o)-f_2(o)\right\vert$ $\forall\:o\in\mathcal{O}$.
\end{enumerate}

\textit{(i) Application of Lemma \ref{lemma:lemma14foster} to show (I)}. Define $\mathcal{F}:=\mathcal{G}_{B_1}$, $t_f(o):=s(o)\cdot f(z)$, and $\mathcal{O}_0:=\{o\in\mathcal{O}\: :\:\text{the subvector }x\text{ of }o\text{ is in }\mathcal{X}_0\}$. We endow $\mathcal{F}$ with the metric $d$ associated with the norm $\Vert\cdot\Vert_{\mathcal{G}}$ of the RKHS $\mathcal{G}$. To show that condition (a) holds first note that $\mathcal{F}= \mathcal{G}_{B_1}\subset\mathcal{L}^2(P_{0,Z})\subset\mathcal{L}^2(P_{0,O})$, and $\mathcal{G}_{B_1}$ is separable because $\mathcal{G}$ is a separable RKHS by Assumption~\ref{ass:K_G} (see Proposition 11.7 of \cite{paulsen2016introduction}). We already argued that (a.1) holds with $b=k_2B_1$, (a.2) holds because the evaluation functionals are continuous in RKHSs, and (a.3) trivially holds.

Condition (b) is trivially satisfied. Condition (c) holds because $ |t_{I_{\mathcal{O}_0}\cdot f_1}(o)-t_{I_{\mathcal{O}_0}\cdot f_2}(o)|=|I_{\mathcal{O}_0}(o)s(o)\left\{f_1(z)-f_2(z)\right\}|\le \Vert s\Vert_\infty |f_1(z)-f_2(z)|\le  \Vert s\Vert_\infty k_2\Vert f_1-f_2\Vert_{\mathcal{G}}$, where the last inequality holds because $\Vert f\Vert_\infty\le k_2\Vert f\Vert_\mathcal{F}$ $\forall f\in\mathcal{F}$. Condition (d) holds because $\mathbb{E}_{P_0}\{|t_{I_{\mathcal{O}_0}\cdot f_1}(O)-t_{I_{\mathcal{O}_0}\cdot f_2}(O)|\}\le\sup_{o\in\mathcal{O}}|t_{I_{\mathcal{O}_0}\cdot f_1}(o)-t_{I_{\mathcal{O}_0}\cdot f_2}(o)|\le  \Vert s\Vert_\infty\cdot k_2\cdot \Vert f_1-f_2\Vert_{\mathcal{G}}$. Condition (e) trivially holds. Arguing as in the proof of (c), condition (f) holds with $L=\Vert s\Vert_{\infty}$.

Before applying Lemma~\ref{lemma:lemma14foster}, note that $I_0\cdot\mathcal{G}_{B_1}$ is star-shaped because $\mathcal{G}_{B_1}$ is star-shaped and multiplication by $I_0$ preserves this. Hence, its critical radius equals that of its star-shaped hull, so the lemma applies with an upper bound on the critical radius of $I_0\cdot\mathcal{G}_{B_1}$.

 Applying Lemma~\ref{lemma:lemma14foster}, we obtain that the display~\eqref{eq:term1sup} happens with probability at least $1-\xi(\delta_n)$ with $c_2=6\cdot \Vert s\Vert_{\infty}/b$ and $b=k_2B_1$. Consequently, the display~\eqref{eq:term1sup} also happens with probability at least $1-\xi(\delta_n)$ with $c_2$ now equal to $6L'/b$ where $L'$ is defined in~\eqref{def:Lmax}.
\smallskip

\textit{(ii) Application of Lemma~\ref{lemma:lemma14foster} to show (II)}. Define $\mathcal{F}$, the metric $d$, and $\mathcal{O}_0$ as in (i). Define $t_f(o):=r(o)\cdot \tilde h(w)\cdot f(z)$. Condition (a) holds as shown in (i). Condition (b) holds trivially. Conditions (c) and (d) hold as shown in (i), using in addition that $\sup_{w\in\mathcal{W}}|\tilde h(w)|\le k_1B$. Condition (e) is immediate. Arguing as in the proof of condition (c) in (i), (f) holds with $L=\Vert r\Vert_{\infty}\cdot k_1B$. Applying Lemma \ref{lemma:lemma14foster}, we obtain that the display~\eqref{eq:term2sup} happens with probability at least $1-\xi(\delta_n)$ with $c_2=6 \Vert r\Vert_{\infty} k_1B/b$ and $b=k_2B_2$. Then, \eqref{eq:term2sup} also happens with probability at least $1-\xi(\delta_n)$ with $c_2$ now equal to $6L'/b$ where $L'$ is defined in~\eqref{def:Lmax}.
\smallskip

\textit{(iii) Application of Lemma \ref{lemma:lemma14foster} to show (III)}. Define $\mathcal{F}$, $d$, and $\mathcal{O}_0$ as in (i). Define $t_f(o):=c^2\cdot f(z)^2$. Condition (a) holds as shown in (i), (b) holds trivially, (c) holds because $  |t_{I_{\mathcal{O}_0}\cdot f_1}(o)-t_{I_{\mathcal{O}_0}\cdot f_2}(o)|=|c^2I_{\mathcal{O}_0}(o)\left\{f_1(z)^2-f_2(z)^2\right\}|
    \le c^2 \left\vert f_1(z)+f_2(z)\right\vert\cdot\left\vert f_1(z)-f_2(z)\right\vert
    \le 2c^2 k_2 B_1\left\vert f_1(z)-f_2(z)\right\vert\le  2c^2 k_2^2 B_1\Vert f_1-f_2\Vert_{\mathcal{G}}$, and (d) holds because $\mathbb{E}_{P_0}\{|t_{I_{\mathcal{O}_0}\cdot f_1}(O)-t_{I_{\mathcal{O}_0}\cdot f_2}(O)|\}\le\sup_{o\in\mathcal{O}}|t_{I_{\mathcal{O}_0}\cdot f_1}(o)-t_{I_{\mathcal{O}_0}\cdot f_2}(o)|\le  2c^2\cdot k_2^2\cdot B_1\cdot \Vert f_1-f_2\Vert_{\mathcal{G}}$. Condition (e) is trivial and condition (f) holds with $L=2c^2 b$ arguing as in the proof of (c).

 Applying Lemma \ref{lemma:lemma14foster}, we obtain that the display~\eqref{eq:term3sup} happens with probability at least $1-\xi(\delta_n)$ with $c_2=6\cdot 2c^2\cdot b/b$ and $b=k_2B_1$. Consequently, the display~\eqref{eq:term3sup} also happens with probability at least $1-\xi(\delta_n)$ with $c_2$ now equal to $6L'/b$ where $L'$ is defined in~\eqref{def:Lmax}.

Setting $c_3=3c_2=18L'/b$ with $L'$ defined in~\eqref{def:Lmax}, with probability at least $1-3\xi(\delta_n)$, we have $\frac{1}{4c^2}\Vert I_0\mathcal{T}(h_0^\dag-\tilde h)\Vert^2_2\le\mathbb{E}_n\{I_0(X)s(O)g_{\tilde h}(Z)-I_0(X)r(O)\tilde h(W)g_{\tilde h}(Z)-c^2 I_0(X)g_{\tilde h}(Z)^2\}+c_3\delta_n\Vert I_0 g_{\tilde h}\Vert_2 +c_3\delta_n^2$.

Then, the following event happens with probability at least $1-3\xi(\delta_n)$, for any $h\in\mathcal{H}_B$:
\begin{align}
      \frac{1}{4c^2}\big\Vert I_0\mathcal{T}\big(&h_0^\dag-\tilde h\big)\big\Vert^2_2\le\mathbb{E}_n\big\{I_0(X)s(O)g_{\tilde h}(Z)-I_0(X)r(O)\tilde h(W)g_{\tilde h}(Z)-c^2 I_0(X)g_{\tilde h}(Z)^2\big\}\nonumber\\
    &\quad-\lambda_{\mathcal{G}}\Vert g_{\tilde h}\Vert^2_{\mathcal{G}}+\lambda_{\mathcal{G}}\Vert g_{\tilde h}\Vert^2_{\mathcal{G}}+c_3\big(\delta_n\Vert I_0\cdot g_{\tilde h}\Vert_2 +\delta_n^2\big)\nonumber\\
    &\le \sup_{g\in\mathcal{G}}\big[\mathbb{E}_n\big\{I_0(X)s(O)g(Z)-I_0(X)r(O)\tilde h(W)g(Z)-c^2 I_0(X)g(Z)^2\big\}-\lambda_{\mathcal{G}}\Vert g\Vert_{\mathcal{G}}^2\big]\nonumber\\
    &\quad+\lambda_{\mathcal{G}}B_1^2+c_3\big(\delta_n\Vert I_0\cdot g_{\tilde h}\Vert_2 +\delta_n^2\big)\nonumber\\
    &\le\sup_{g\in\mathcal{G}}\big[\mathbb{E}_n\big\{I_0(X)s(O)g(Z)-I_0(X)r(O)h(W)g(Z)-c^2 I_0(X)g(Z)^2\big\}-\lambda_{\mathcal{G}}\Vert g\Vert_{\mathcal{G}}^2\big]\nonumber\\
&\quad+\lambda_{\mathcal{G}}B_1^2+\lambda_{\mathcal{H}}\Big(\big\Vert h\big\Vert_{\mathcal{H}}^2-\big\Vert \tilde h\big\Vert_{\mathcal{H}}^2\Big)+c_3\big(\delta_n\Vert I_0\cdot g_{\tilde h}\Vert_2 +\delta_n^2\big).\label{last_line_emr_step}
\end{align}

Note that the second inequality is always true because $g_{\tilde h}\in \mathcal{G}_{B_1}$, and the third inequality is also true because $\tilde h$ is the empirical risk minimizer defined in~\eqref{def:h_tilde}.

Set $c_4:=\max\{c_3[1+c_3/(2c^2)], 5c_2^2/c^2\}$. For any $h\in\mathcal{H}_B$, we define
\begin{align*}
    T_n(h)&:=\sup_{g\in\mathcal{G}}\mathbb{E}_{P_0}\big\{I_0(X)s(O)g(Z)-I_0(X)r(O)h(W) g(Z)-\frac{c^2}{2}\cdot I_0(X) g(Z)^2\big\}+c_4\delta_n^2,\\
    A_n(h)&:=\sup_{g\in\mathcal{G}_{B_1}}\left[\mathbb{E}_n\big\{I_0(X)s(O)g(Z)-I_0(X)r(O)h(W)g(Z)-c^2 I_0(X)g(Z)^2\big\}-\lambda_{\mathcal{G}}\Vert g\Vert_{\mathcal{G}}^2\right]\\
    B_n(h)&:=\sup_{g\in\mathcal{G}\setminus\mathcal{G}_{B_1}}\left[\mathbb{E}_n\big\{I_0(X)s(O)g(Z)-I_0(X)r(O)h(W)g(Z)-c^2 I_0(X)g(Z)^2\big\}-\lambda_{\mathcal{G}}\Vert g\Vert_{\mathcal{G}}^2\right],\\
    \text{and}\quad&\\
    C_n(h)&:= \sup_{g\in\mathcal{G}}\left[\mathbb{E}_n\big\{I_0(X)s(O)g(Z)-I_0(X)r(O)h(W)g(Z)-c^2\cdot I_0(X)g(Z)^2\big\}-\lambda_{\mathcal{G}}\Vert g\Vert_{\mathcal{G}}^2\right].
\end{align*}

Below we will show that, with probability at least $1-3\xi(\delta_n)$, each of the following event happens: $A_n(h)\le T_n(h)$ and $B_n(h)\le T_n(h)$. This will then imply that with probability at least $1-6\xi(\delta_n)$ for any $h\in\mathcal{H}_B$: 
\begin{align}
   C_n(h)\le T_n(h).\label{eq:emr_step_both}
\end{align}

Assume for now that the last assertion holds. By part 1 of Proposition~\ref{prop:innermax} and Assumption~\ref{ass:closeness}, we have that $\sup_{g\in\mathcal{G}}\mathbb{E}_{P_0}\{I_0(X)s(O)g(Z)-I_0(X)r(O)h(W)g(Z)-\frac{c^2}{2} I_0(X)g(Z)^2\}=\frac{1}{2c^2}\Vert I_0\mathcal{T}(h_0^\dag-h)\Vert^2_2$. Combining this equality with the inequalities in~\eqref{last_line_emr_step} and~\eqref{eq:emr_step_both}, we then conclude that with probability at least $1-9\xi(\delta_n)$, for any $h\in\mathcal{H}_B$:
\begin{align}
    \frac{1}{4c^2}\big\Vert I_0\mathcal{T}\big(h_0^\dag-\tilde h \big)\big\Vert^2_2\le&  \frac{1}{2c^2}\big\Vert I_0\mathcal{T}\big(h_0^\dag-h\big)\big\Vert^2_2+\lambda_{\mathcal{H}}\Big(\big\Vert h\big\Vert_{\mathcal{H}}^2-\big\Vert \tilde h\big\Vert_{\mathcal{H}}^2\Big)+\lambda_{\mathcal{G}}B_1^2\nonumber \\
    &\quad+c_3\cdot\delta_n\Vert  I_0\cdot g_{\tilde h}\Vert_2 +\left(c_3+c_4\right)\delta_n^2\label{ineq_aux}.
\end{align}

Furthermore, by the triangle inequality $\Vert I_0\mathcal{T}(h_0^\dag-\tilde h)\Vert_2\le \Vert I_0\mathcal{T}(h_0^\dag-h)\Vert_2+\Vert I_0\mathcal{T}(\tilde h-h)\Vert_2$ and since $\Vert I_0\cdot g_{\tilde h}\Vert_2=\frac{1}{2c^2}\Vert I_0\mathcal{T}(h_0^\dag-\tilde h)\Vert_2$, the inequality~\eqref{ineq_aux} implies that the following event happens with probability at least $1-9\xi(\delta_n)$ for any $h\in\mathcal{H}_B$
\begin{align*}
     \frac{1}{4c^2}\big\Vert I_0\mathcal{T}\big(h_0^\dag-\tilde h\big)\big\Vert^2_2\le&\frac{1}{2c^2}\big\Vert I_0\mathcal{T}\big(h_0^\dag-h\big)\big\Vert^2_2+\lambda_{\mathcal{H}}\Big(\big\Vert h\big\Vert_{\mathcal{H}}^2-\big\Vert \tilde h\big\Vert_{\mathcal{H}}^2\Big)+\lambda_{\mathcal{G}}B_1^2\\
    &+\frac{c_3}{2c^2}\Big\{\delta_n\big\Vert I_0\mathcal{T}\big(h_0^\dag-h\big)\big\Vert_2+\delta_n\big\Vert I_0\mathcal{T}\big(\tilde h-h\big)\big\Vert_2\Big\}+(c_3+c_4)\delta_n^2.
\end{align*}
By the AM-GM inequality $\frac{c_3}{2c^2}\delta_n \Vert I_0\mathcal{T}(h_0^\dag-h)\Vert_2\le\frac{1}{4c^2}\Vert I_0\mathcal{T}(h_0^\dag-h)\Vert_2^2+\frac{c_3^2}{4c^2}\delta_n^2$. Hence, the following event happens with probability at least $1-9\xi(\delta_n)$ for all $h\in\mathcal{H}_B$:
\begin{align*}
    \frac{1}{4c^2}&\Big\{\big\Vert I_0\mathcal{T}\big(h_0^\dag-\tilde h\big)\big\Vert^2_2-\big\Vert I_0\mathcal{T}\big(h_0^\dag-h\big)\big\Vert^2_2\Big\}+\lambda_{\mathcal{H}}\Big(\big\Vert \tilde h\big\Vert_{\mathcal{H}}^2-\big\Vert h\big\Vert_{\mathcal{H}}^2\Big)\\
    &\quad\quad\quad\le \frac{1}{2c^2}\big\Vert I_0\mathcal{T}\big(h_0^\dag-h\big)\big\Vert^2_2+\frac{c_3}{2c^2}\delta_n\big\Vert I_0\mathcal{T}\big(\tilde h-h\big)\big\Vert_2+\lambda_{\mathcal{G}}B_1^2+\Big(c_3+c_4+\frac{c_3^2}{4c^2}\Big)\delta^2_n,
\end{align*}
thus, arriving at the desired inequality.

We now turn to prove that $A_n(h)\le T_n(h)$ holds with probability at least $1-3\xi(\delta_n)$. Fix $h\in\mathcal{H}_B$ and take $g\in\mathcal{G}_{B_1}$. Applying Lemma~\ref{lemma:lemma14foster} as we did to show (I), (II), and (III), and noting that $-\lambda_{\mathcal{G}}\Vert g\Vert_{\mathcal{G}}^2\le0$, we have that the following event happens with probability at least $1-3\xi(\delta_n)$, 
\begin{align}
&\mathbb{E}_n\big\{I_0(X)s(O)g(Z)-I_0(X)r(O)h(W)g(Z)-c^2I_0(X)g(Z)^2\big\}-\lambda_{\mathcal{G}}\Vert g\Vert_{\mathcal{G}}^2\label{eq:bound_case1}\\
    &\le E_{P_0}\big\{I_0(X)s(O)g(Z)-I_0(X)r(O)h(W)g(Z)-c^2I_0(X) g(Z)^2\big\}+c_3\delta_n\Vert I_0\cdot  g\Vert_2+c_3\delta_n^2.\nonumber
\end{align}

By the AM-GM inequality, $c_3\delta_n\Vert I_0\cdot g\Vert_2\le \frac{c^2}{2}\Vert I_0\cdot g\Vert_2^2+\frac{c_3^2}{2c^2}\delta_n^2$. Hence, the right-hand side of (\ref{eq:bound_case1}) is upper bounded by
\begin{align*}
    \sup_{g\in\mathcal{G}}\mathbb{E}_{P_0}\Big\{I_0(X)s(O)g(Z)-I_0(X)r(O)h(W)g(Z)-\frac{c^2}{2} I_0(X)g(Z)^2\Big\}+\left(c_3+\frac{c^2_3}{2c^2}\right)\delta_n^2\le T_n(h).
\end{align*}
Since $g\in\mathcal{G}_{B_1}$ was arbitrary, $A_n(h)\le T_n(h)$ happens with probability at least $1-3\xi(\delta_n)$.

Turn now to prove that $B_n(h)\le T_n(h)$ holds with probability at least $1-3\xi(\delta_n)$. Fix $h\in\mathcal{H}_B$ and take $g\in\mathcal{G}\setminus\mathcal{G}_{B_1}$. Then, $\Vert g\Vert_{\mathcal{G}}>B_1$. Define $\tilde g:=B_1\cdot  g/\Vert g\Vert_{\mathcal{G}}$. Since $\mathcal{G}$ is star-shaped and $B_1/\Vert g\Vert_{\mathcal{G}}\in(0,1)$, $\tilde g\in\mathcal{G}$. Furthermore, $\Vert\tilde g\Vert_{\mathcal{G}}=B_1$, and so $\tilde g\in\mathcal{G}_{B_1}$. Applying Lemma~\ref{lemma:lemma14foster} as we did to prove (I) and (II), we obtain that, with probability at least $1-2\xi(\delta_n)$,  the following happens:
\begin{align*}
 \mathbb{E}_n\big\{I_0(X)&s(O)g(Z)-I_0(X)r(O)h(W)g(Z)\big\}\\
    &=\frac{\Vert g\Vert_\mathcal{G}}{B_1}\cdot \mathbb{E}_n\big\{I_0(X)s(O)\tilde g(Z)-I_0(X)r(O)h(W)\tilde g(Z)\big\}\\
    &\le \frac{\Vert g\Vert_\mathcal{G}}{B_1}\cdot \big[\mathbb{E}_{P_0}\big\{I_0(X)s(O)\tilde g(Z)-I_0(X)r(O)h(W)\tilde g(Z)\big\}+2c_2\delta_n\Vert I_0\cdot \tilde g\Vert_2+2c_2\delta_n^2\big]\\
    &=\mathbb{E}_{P_0}\big\{I_0(X)s(O)g(Z)-I_0(X)r(O)h(W)g(Z)\big\}+2c_2\delta_n\Vert I_0\cdot g\Vert_2+\frac{2c_2}{B_1}\Vert g\Vert_\mathcal{G}\cdot\delta_n^2,
\end{align*}
where $c_2=6L'/b$, with $L'$ defined in~\eqref{def:Lmax}. Applying Lemma~\ref{lemma:lemma14foster} as we did to prove (III), with probability at least $1-\xi(\delta_n)$, the following event happens:
\begin{align*}
    - \mathbb{E}_n\big\{c^2 I_0(X) g(Z)^2\big\}&=-\frac{\Vert g\Vert_\mathcal{G}^2}{B_1^2} \mathbb{E}_n\big\{c^2 I_0(X)\tilde g(Z)^2\big\}\\
    &\le \frac{\Vert g\Vert_\mathcal{G}^2}{B_1^2} \left[-\mathbb{E}_{P_0}\big\{c^2I_0(X)\tilde g(Z)^2\big\}+12c^2\delta_n\left(\Vert I_0\cdot \tilde g\Vert_2+\delta_n\right)\right]\\
    &=-\mathbb{E}_{P_0}\big\{c^2 I_0(X) g(Z)^2\big\}+\frac{12c^2}{B_1}\delta_n\Vert g\Vert_\mathcal{G}\cdot \Vert I_0\cdot  g\Vert_2+\frac{12c^2}{ B_1^2}\Vert g\Vert_\mathcal{G}^2\cdot\delta_n^2.
\end{align*}

Hence, with probability at least $1-3\xi(\delta_n)$, the following event happens:
\begin{align}
\mathbb{E}_n&\big\{I_0(X)s(O)g(Z)-I_0(X)r(O)h(W)g(Z)-c^2 I_0(X)g(Z)^2\big\}-\lambda_{\mathcal{G}}\Vert g\Vert_{\mathcal{G}}^2\nonumber\\
    &\le \mathbb{E}_P\big\{I_0(X)s(O)g(Z)-I_0(X)r(O)h(W)g(Z)-c^2 I_0(X) g(Z)^2\big\}-\lambda_{\mathcal{G}}\Vert g\Vert_{\mathcal{G}}^2\label{eq:bound_case2}\\
    &\quad+2c_2\delta_n\Vert I_0\cdot g\Vert_2+\frac{2c_2}{B_1}\Vert g\Vert_\mathcal{G}\cdot\delta_n^2+\frac{12c^2}{B_1}\delta_n\Vert g\Vert_\mathcal{G}\cdot \Vert I_0\cdot  g\Vert_2+\frac{12c^2}{ B_1^2}\Vert g\Vert_\mathcal{G}^2\cdot\delta_n^2.\nonumber
\end{align}

Applying the AM-GM inequality, we obtain (1) $ 2c_2\delta_n\Vert I_0\cdot g\Vert_2\le \frac{c^2}{4}\Vert I_0\cdot g\Vert_2^2+\frac{4c_2^2}{c^2}\delta_n^2$, (2) $\frac{2c_2}{B_1}\Vert g\Vert_\mathcal{G}\cdot\delta_n^2\le \frac{c_2^2}{c^2}\delta_n^2+\frac{c^2}{B_1^2}\Vert  g\Vert_\mathcal{G}^2\cdot\delta_n^2$, and (3) $\frac{12c^2}{B_1}\delta_n\Vert g\Vert_\mathcal{G}\cdot \Vert I_0\cdot  g\Vert_2\le \frac{c^2}{4}\Vert I_0\cdot g\Vert_2^2+\frac{144c^2}{B_1^2}\Vert g\Vert_\mathcal{G}^2\cdot\delta_n^2.$
Using these inequalities and the fact that $\lambda_\mathcal{G}\ge 157c ^2\cdot\delta_n^2/B_1^2$, the right-hand side of~\eqref{eq:bound_case2} is upper bounded by $ E_{P_0}\{I_0(X)s(O)g(Z)-I_0(X)r(O)h(W)g(Z)-\frac{c^2}{2} I_0(X) g(Z)^2\}+\frac{5c_2^2}{c^2}\delta_n^2\le\sup_{g\in\mathcal{G}} E_{P_0}\big\{m(O; g)-I_0(X)r(O)h(W)g(Z)-\frac{c^2}{2} I_0(X) g(Z)^2\big\}+\frac{5c_2^2}{c^2}\delta_n^2\le T_n(h)$. Thus, $B_n(h)\le T_n(h)$ holds with probability at least $1-3\xi(\delta_n)$. This completes the proof.

Under the assumptions of Theorem~\ref{theo:main} and with $\lambda_\mathcal{G}\ge 157c^2/B_1^2$, with probability at least $1-\{36+18\cdot I\{\delta_n<5b/6\}\lfloor\{\log(6/5)\}^{-1} \log(b/\delta_n)\rfloor\}\exp(-c_1n\delta_n^2)$, the following event happens for any $h\in \mathcal{H}_{B}$:
\begin{align*}
    \frac{1}{4c^2}\Big\{\big\Vert I_0 \mathcal{T} \big(h_0^\dag-&\tilde h\big)\big\Vert^2_2-\big\Vert I_0\mathcal{T} \big(h_0^\dag-h\big)\big\Vert^2_2\Big\}+\lambda_{\mathcal{H}}\Big(\big\Vert \tilde h\big\Vert_{\mathcal{H}}^2-\big\Vert h\big\Vert_{\mathcal{H}}^2\Big)\\
     &\quad\quad\quad\le \frac{1}{2c^2}\big\Vert I_0\mathcal{T} \big(h_0^\dag-h\big)\big\Vert^2_2+c_0\delta_n\big\Vert  I_0\mathcal{T}\big(\tilde h-h\big)\big\Vert_2+\lambda_{\mathcal{G}}B_1^2+c_0'\delta^2_n,
\end{align*}
where $\tilde h=\arg\min_{h\in\mathcal{H}_{B}}\max_{g\in\mathcal{G}}\{\mathbb{E}_n[\{m(O;g) -I_0(X)r(O)h(W)g(Z)-c^2I_0(X)g(Z)^2\}]-\lambda_{\mathcal{G}}\Vert g\Vert_{\mathcal{G}}^2+\lambda_{\mathcal{H}}\Vert h\Vert_{\mathcal{H}}^2\}$, $c_0:=3\cdot\max\{3,B_2+2\}\cdot \max\{1\:\Vert r\Vert_\infty\cdot k_1B,\: 2c^2b\}/(c^2 b)$, $b=B_1\max\{k_2,B_3\}$, with $B_2$ and $B_3$ the constants in Assumption~\ref{ass:bounded}, and $c_1$ and $c'_0$ are defined as in Lemma~\ref{lemma:erm}.\label{lemma:erm_mg}
